// 静态公账2只凭显式作者与三段同版准入；旧缺省目录输出保持原字节形状。
#include "resident/domains/politics/takeover/politics_takeover_profile.hpp"
#include "resident/domains/politics/takeover/politics_takeover_catalog.hpp"
#include "resident/domains/politics/takeover/politics_takeover_detail.hpp"
#include <iostream>
using namespace hanmo::resident;
int main(){int checks=0;auto check=[&](bool ok,const char* name){++checks;if(!ok){std::cerr<<name<<'\n';std::exit(1);}};
 PoliticalTakeoverCatalog old;auto encoded=encode_political_takeover_catalog(old);check(!encoded.find("task_execution_version"),"default catalog omits new field");auto decoded=decode_political_takeover_catalog(encoded);check(decoded.ok&&decoded.value.task_execution_version==1,"old catalog defaults one");check(compare_boundary(encoded,encode_political_takeover_catalog(decoded.value)).exact(),"old catalog exact roundtrip");
 old.enabled=true;old.task_execution_version=2;auto newer=encode_political_takeover_catalog(old);auto parsed=decode_political_takeover_catalog(newer);check(parsed.ok&&parsed.value.task_execution_version==2,"explicit two catalog");old.task_execution_version=3;check(!decode_political_takeover_catalog(encode_political_takeover_catalog(old)).ok,"unknown catalog version rejected");old.enabled=false;old.task_execution_version=2;check(!decode_political_takeover_catalog(encode_political_takeover_catalog(old)).ok,"disabled two catalog rejected");
 PoliticalTakeoverState state;std::vector<std::pair<StableId,StableId>> modules{{"political_takeover","1"},{"economic_takeover_execution","1"},{"task_takeover_execution","1"}};
 check(validate_political_takeover_layout(true,modules,&state,1,1).ok,"legacy triple");modules.back().second="2";check(validate_political_takeover_layout(true,modules,&state,1,2,2).ok,"task2 triple");check(!validate_political_takeover_layout(true,modules,&state,1,1,2).ok,"task state mismatched");check(!validate_political_takeover_layout(true,modules,&state,1,2,1).ok,"author mismatched");modules[1].second="2";check(!validate_political_takeover_layout(true,modules,&state,2,2,2).ok,"economic remains one");modules[1].second="1";modules.pop_back();check(!validate_political_takeover_layout(true,modules,&state,1,2,2).ok,"missing marker rejected");modules.push_back({"task_takeover_execution","2"});modules.push_back(modules.back());check(!validate_political_takeover_layout(true,modules,&state,1,2,2).ok,"duplicate marker rejected");check(!validate_political_takeover_layout(false,modules,nullptr).ok,"disabled marker rejected");check(validate_political_takeover_layout(false,{},nullptr).ok,"disabled legacy empty");
 PoliticalOriginalResponsibility source;source.responsibility={PoliticalResponsibilityKind::task_contract,"task:1",{},{}};source.principal=SubjectRef{SubjectKind::organization,"old"};source.assignee=SubjectRef{SubjectKind::actor,"actor"};source.containers.push_back({"wallet","funding",false,true,{},Owner{Owner::Kind::organization,"old"}});PoliticalResponsibilityRequest request;request.responsibility=source.responsibility;request.disposition=PoliticalResponsibilityDisposition::assume_by_successor;
 auto unsupported=takeover_detail::derive(source,request,"new","old");check(!unsupported.ok,"static old source denied");source.record_sources.push_back({"static_task_cash_v2","task:1"});check(takeover_detail::derive(source,request,"new","old").ok,"typed static cash marker admitted");source.containers.push_back({"inventory","delivery",true,true,{},Owner{Owner::Kind::organization,"old"}});check(!takeover_detail::derive(source,request,"new","old").ok,"static delivery capture denied");std::cout<<checks<<" checks 0 failures\n";
}
